examples.template:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
    Toggle(isOn: $first) {
        VStack(alignment: .leading) {
            Text({{items.0.label}}).monarchTextStyle(.body)
            Text({{items.0.description}}).monarchTextStyle(.caption)
        }
    }
    Toggle({{items.1.label}}, isOn: $second)
}

examples.code:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
    Toggle(isOn: $first) {
        VStack(alignment: .leading) {
            Text("Two-step sign-in").monarchTextStyle(.body)
            Text("Ask for a PIN on new devices.").monarchTextStyle(.caption)
        }
    }
    Toggle("Compact rail", isOn: $second)
}
